        builder.Property(s => s.Precio1).HasColumnType("decimal(10,2)").IsRequired();
        builder.Property(s => s.Precio2).HasColumnType("decimal(10,2)").IsRequired();
        builder.Property(s => s.Precio3).HasColumnType("decimal(10,2)").IsRequired();
